drop view if exists api.astro_events; create view api.astro_events with (security_invoker = true) as select ae.id, ae.event_date, ae.sunrise, ae.sunset, ae.day_length_seconds, ae.moon_rise, ae.moon_set, ae.moon_phase, ae.moon_illumination, ae.moon_age_days, ae.moon_sign, ae.lunar_month_day, ae.next_new_moon, ae.next_full_moon, ae.is_equinox, ae.is_solstice, ae.season, ae.tenant_id, p.display_name as calculated_by from spiritual.astro_events ae join identity.profiles p on p.id = ae.calculated_by;
